using System.Security.Claims;
using System.Text.Json;
using AeroScience.Missions;
using AeroScience.Shared;
using Microsoft.EntityFrameworkCore;
namespace AeroScience.Organization;

public sealed partial class OrganizationCampaignProgress
{
    IQueryable<CampaignCoverageObservation> CoverageFacts(Guid campaign,CampaignCoverageFilter f)
    {
        var q=from o in db.CoverageObservations.AsNoTracking() join c in Accepted() on new{o.RootId,o.CardId} equals new{c.RootId,c.CardId}
            join i in db.CoverageIndexes.AsNoTracking() on o.RootId equals i.RootId
            where o.CampaignId==campaign&&i.Version==1&&i.Valid&&i.ReviewRevision==c.ReviewRevision&&i.HeadSha256==c.SourceHeadSha256 select o;
        if(f.OpportunityId is {} id)q=q.Where(o=>o.OpportunityId==id);else q=q.Where(o=>db.Opportunities.Any(p=>p.Id==o.OpportunityId&&p.PublishedRevision==o.PublicationRevision&&p.PublishedSha256==o.PublicationSha256));
        if(f.PublicationRevision is {} revision)q=q.Where(o=>o.PublicationRevision==revision);else if(f.OpportunityId is {} opportunity)q=q.Where(o=>db.Opportunities.Any(p=>p.Id==opportunity&&p.PublishedRevision==o.PublicationRevision&&p.PublishedSha256==o.PublicationSha256));
        if(f.CompatibilityId is {} compatible)q=q.Where(o=>o.CompatibilityId==compatible);
        if(f.RequirementKey is {} requirement)q=q.Where(o=>o.RequirementKey==requirement);
        if(f.Variable is {} variable)q=q.Where(o=>o.Variable==variable);if(f.Instrument is {} instrument)q=q.Where(o=>o.Instrument==instrument);if(f.Category is {} category)q=q.Where(o=>o.Category==category);
        if(f.FromUtc is {} start)q=q.Where(o=>o.TimestampUtc>=start);if(f.ThroughUtc is {} end)q=q.Where(o=>o.TimestampUtc<=end);if(f.FlightReference is {} flight)q=q.Where(o=>o.FlightReference==flight);return q;
    }
    static void CoverageFilter(CampaignCoverageFilter f,int offset=0)
    {
        if(offset<0||f.CompatibilityId is not null&&!CampaignCoverageRules.Hash(f.CompatibilityId)||f.PublicationRevision is <=0||f.PublicationRevision is not null&&f.OpportunityId is null||f.Variable?.Length>120||f.Instrument?.Length>80||f.RequirementKey?.Length>120||f.FlightReference?.Length>80||f.Category is {} c&&!Enum.IsDefined(c)||f.FromUtc is {} from&&from.Offset!=TimeSpan.Zero||f.ThroughUtc is {} to&&to.Offset!=TimeSpan.Zero||f.FromUtc>f.ThroughUtc)throw new ArgumentException("Choose supported coverage filters, an exact published version and an ordered UTC observation window.");
    }
    // A canonical reference is an index pointer, not another scientific reading. Both contradictory
    // original hashes and a shared original claimed by different pilots are excluded from credit.
    static IQueryable<CampaignCoverageObservation> UniqueCoverage(IQueryable<CampaignCoverageObservation> q)=>q.Where(o=>
        !q.Any(d=>d.CompatibilityId==o.CompatibilityId&&d.IdentitySha256==o.IdentitySha256&&(d.ContentSha256!=o.ContentSha256||d.PilotId!=o.PilotId))&&
        !q.Any(d=>d.CompatibilityId==o.CompatibilityId&&d.IdentitySha256==o.IdentitySha256&&d.ReferenceId.CompareTo(o.ReferenceId)<0));
    static async Task<CoverageCounts> CoverageCount(IQueryable<CampaignCoverageObservation> q,CancellationToken ct)
    {return await q.GroupBy(_=>1).Select(g=>new CoverageCounts(g.LongCount(),g.Select(o=>o.FlightId).Distinct().LongCount(),g.Select(o=>o.Date).Distinct().LongCount(),g.Select(o=>o.PilotId).Distinct().LongCount(),g.LongCount(o=>o.Latitude!=null&&o.Longitude!=null))).SingleOrDefaultAsync(ct)??new(0,0,0,0);}
    async Task<long> MissingCoverage(Guid campaign,CancellationToken ct)=>await Accepted().Where(c=>c.CampaignId==campaign&&!db.CoverageIndexes.Any(i=>i.RootId==c.RootId&&i.Version==1&&i.Valid&&i.ReviewRevision==c.ReviewRevision&&i.HeadSha256==c.SourceHeadSha256)).LongCountAsync(ct);
    public Task<CampaignCoverageView> Coverage(Guid campaign,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{
        var published=await Publication(campaign,ct);var accepted=await Accepted().Where(c=>c.CampaignId==campaign).LongCountAsync(ct);var missing=await MissingCoverage(campaign,ct);return new CampaignCoverageView(1,r.Organization,campaign,published.Name,r.At,!r.Native&&r.Role is OrganizationRoles.Administrator or OrganizationRoles.Manager,accepted,accepted-missing,missing,await db.CoverageGoals.AnyAsync(g=>g.CampaignId==campaign,ct),CampaignCoverageRules.Methods,CampaignCoverageRules.Variables());
    },ct);
    public Task<OrganizationPage<CoverageGroup>> CoverageGroups(Guid campaign,CampaignCoverageFilter filter,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{
        CoverageFilter(filter,offset);_=await Publication(campaign,ct);var facts=CoverageFacts(campaign,filter);var ids=await facts.Select(o=>o.CompatibilityId).Distinct().Order().Skip(offset).Take(21).ToArrayAsync(ct);var values=new List<CoverageGroup>();
        foreach(var id in ids.Take(20)){var all=facts.Where(o=>o.CompatibilityId==id);var q=UniqueCoverage(all);var row=await all.OrderBy(o=>o.ReferenceId).FirstAsync(ct);var counts=await CoverageCount(q,ct);var conflicts=await all.Where(o=>all.Any(d=>d.IdentitySha256==o.IdentitySha256&&(d.ContentSha256!=o.ContentSha256||d.PilotId!=o.PilotId))).Select(o=>o.IdentitySha256).Distinct().LongCountAsync(ct);var duplicates=await all.Where(o=>!all.Any(d=>d.IdentitySha256==o.IdentitySha256&&(d.ContentSha256!=o.ContentSha256||d.PilotId!=o.PilotId))).LongCountAsync(ct)-counts.Observations;
            var extrema=await q.GroupBy(_=>1).Select(g=>new{Start=(DateTimeOffset?)g.Min(o=>o.TimestampUtc),End=(DateTimeOffset?)g.Max(o=>o.TimestampUtc),Altitude=g.LongCount(o=>o.AltitudeFeetMsl!=null)}).SingleOrDefaultAsync(ct);
            values.Add(new(id,row.OpportunityId,row.PublicationRevision,row.PublicationSha256,row.Variable,row.Name,row.Instrument,row.Unit,row.Provenance,row.Category,row.SourceSemanticsSha256,counts.Observations,counts.Flights,counts.Dates,counts.Pilots,counts.LocatedObservations,extrema?.Altitude??0,duplicates,conflicts,extrema?.Start,extrema?.End));}
        return new OrganizationPage<CoverageGroup>(1,values.ToArray(),ids.Length>20?checked(offset+20):null);
    },ct);
    public Task<OrganizationPage<CoverageLocation>> CoverageLocations(Guid campaign,CampaignCoverageFilter filter,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{
        CoverageFilter(filter,offset);_=await Publication(campaign,ct);var q=UniqueCoverage(CoverageFacts(campaign,filter)).Where(o=>o.Latitude!=null&&o.Longitude!=null);var rows=await q.OrderBy(o=>o.TimestampUtc).ThenBy(o=>o.IdentitySha256).ThenBy(o=>o.CompatibilityId).Skip(offset).Take(101).ToArrayAsync(ct);
        return new OrganizationPage<CoverageLocation>(1,rows.Take(100).Select(o=>new CoverageLocation(PreflightReadiness.Hash(new{r.Organization,o.IdentitySha256}),o.CompatibilityId,o.Variable,o.Instrument,o.Unit,o.Provenance,o.Category,o.Contributor,o.FlightReference,o.TimestampUtc,o.Latitude!.Value,o.Longitude!.Value,o.AltitudeFeetMsl,o.RootId,o.CardId,o.RequirementKey)).ToArray(),rows.Length>100?checked(offset+100):null);
    },ct);
    public Task<OrganizationPage<CoverageBand>> CoverageAltitude(Guid campaign,CampaignCoverageFilter filter,int offset,double bandFeet,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{
        CoverageFilter(filter,offset);_=await Publication(campaign,ct);if(filter.CompatibilityId is null||!double.IsFinite(bandFeet)||bandFeet is <100 or >20000)throw new ArgumentException("Select one scientifically compatible group and a display band width of 100–20,000 feet MSL.");
        var q=UniqueCoverage(CoverageFacts(campaign,filter)).Where(o=>o.AltitudeFeetMsl!=null);var rows=await q.GroupBy(o=>(int)Math.Floor(o.AltitudeFeetMsl!.Value/bandFeet)).OrderBy(g=>g.Key).Select(g=>new{Band=g.Key,Count=g.LongCount(),Flights=g.Select(o=>o.FlightId).Distinct().LongCount(),Dates=g.Select(o=>o.Date).Distinct().LongCount(),Pilots=g.Select(o=>o.PilotId).Distinct().LongCount(),Located=g.LongCount(o=>o.Latitude!=null&&o.Longitude!=null)}).Skip(offset).Take(21).ToArrayAsync(ct);
        return new OrganizationPage<CoverageBand>(1,rows.Take(20).Select(v=>new CoverageBand(v.Band,v.Band*bandFeet,(v.Band+1)*bandFeet,false,new(v.Count,v.Flights,v.Dates,v.Pilots,v.Located),null,"Observed point sampling only — No target defined for these display bins.")).ToArray(),rows.Length>20?checked(offset+20):null);
    },ct);
    public Task<OrganizationPage<CoverageTemporalSlice>> CoverageDates(Guid campaign,CampaignCoverageFilter filter,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{
        CoverageFilter(filter,offset);_=await Publication(campaign,ct);if(filter.CompatibilityId is null)throw new ArgumentException("Select one compatible source/variable group before comparing dates.");var q=UniqueCoverage(CoverageFacts(campaign,filter));
        var rows=await q.GroupBy(o=>o.Date).OrderBy(g=>g.Key).Select(g=>new{Date=g.Key,Count=g.LongCount(),Flights=g.Select(o=>o.FlightId).Distinct().LongCount(),Pilots=g.Select(o=>o.PilotId).Distinct().LongCount(),Located=g.LongCount(o=>o.Latitude!=null&&o.Longitude!=null)}).Skip(offset).Take(21).ToArrayAsync(ct);
        return new OrganizationPage<CoverageTemporalSlice>(1,rows.Take(20).Select(v=>new CoverageTemporalSlice(v.Date,new(v.Count,v.Flights,1,v.Pilots,v.Located),Math.Max(0,v.Count-1))).ToArray(),rows.Length>20?checked(offset+20):null);
    },ct);
    public async Task<CoverageGoalView> SaveCoverageGoal(Guid campaign,Guid? goal,CoverageGoalSave request,ClaimsPrincipal actor,CancellationToken ct)
    {
        if(request.Version!=1||request.RequestId==Guid.Empty||request.ExpectedRevision<0||goal is null&&request.ExpectedRevision!=0||goal is not null&&request.ExpectedRevision==0)throw new ArgumentException("Use the saved coverage goal revision and a new command identity.");CampaignCoverageRules.Validate(request.Definition);
        async Task Authorize(){await db.Database.ExecuteSqlRawAsync($"SELECT pg_advisory_xact_lock({OrganizationMembership.MembershipLock})",ct);var member=await members.Current(actor,ct);if(member is null)throw new OrganizationForbidden();var stamp=await db.Users.AsNoTracking().Where(u=>u.Id==member.UserId).Select(u=>u.SecurityStamp).SingleOrDefaultAsync(ct);if(stamp is null||stamp!=actor.FindFirstValue("AspNet.Identity.SecurityStamp"))throw new OrganizationUnauthorized();if(member is null||member.State!=OrganizationMembershipState.Active||member.Role is not(OrganizationRoles.Administrator or OrganizationRoles.Manager))throw new OrganizationForbidden();}
        return await history.Mutate(actor,request.RequestId,new{operation="coverage-goal",campaign,goal,request},async(id,name)=>{
            _=await Publication(campaign,ct);var publication=await CardPublication(request.Definition.OpportunityId,request.Definition.PublicationRevision,ct);if(publication.CampaignId!=campaign||PreflightReadiness.Hash(publication)!=request.Definition.PublicationSha256)throw new ArgumentException("Select this campaign's exact published card revision; names alone do not establish matching criteria.");
            var row=goal is {} key?await db.CoverageGoals.SingleOrDefaultAsync(g=>g.Id==key&&g.CampaignId==campaign,ct)??throw new OrganizationNotFound():new CampaignCoverageGoalRecord{Id=Guid.NewGuid(),CampaignId=campaign};if(row.Revision!=request.ExpectedRevision)throw new OrganizationConflict("This coverage goal changed. Your draft is unchanged; reload its current revision.");
            row.Revision++;row.Name=request.Definition.Name;row.SearchName=row.Name.ToUpperInvariant();row.UpdatedUtc=OrganizationTime.UtcNow;var result=new CoverageGoalView(row.Id,campaign,row.Revision,request.Definition,row.UpdatedUtc,PreflightReadiness.Hash(request.Definition),true,publication.Revision!=(await db.Opportunities.AsNoTracking().SingleAsync(o=>o.Id==publication.Id,ct)).PublishedRevision);row.SnapshotJson=JsonSerializer.Serialize(result,WireJson.Options);if(goal is null)db.CoverageGoals.Add(row);history.Revision(row.Id,row.Revision,"coverage-goal",result,id);history.Audit(id,name,goal is null?"coverage-goal-created":"coverage-goal-revised",row.Id,row.Revision);return result;
        },ct,Authorize);
    }
    async Task<CoverageGoalView> Goal(Guid id,int? revision,CancellationToken ct)
    {var row=await db.CoverageGoals.AsNoTracking().SingleOrDefaultAsync(g=>g.Id==id,ct)??throw new OrganizationNotFound();_=await Publication(row.CampaignId,ct);var original=await history.ReadRevision(id,revision??row.Revision,ct);if(original.Kind!="coverage-goal")throw new OrganizationNotFound();var view=Read<CoverageGoalView>(original.SnapshotJson);if(view.Id!=id||view.CampaignId!=row.CampaignId||view.Revision!=original.Revision||view.Sha256!=PreflightReadiness.Hash(view.Definition))throw new InvalidOperationException("Original coverage goal identity could not be verified.");CampaignCoverageRules.Validate(view.Definition);return view with{Current=view.Revision==row.Revision,HistoricalPublication=view.Definition.PublicationRevision!=(await db.Opportunities.AsNoTracking().SingleAsync(o=>o.Id==view.Definition.OpportunityId,ct)).PublishedRevision};}
    public Task<CoverageGoalView> CoverageGoal(Guid id,int? revision,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,r=>Goal(id,revision,ct),ct);
    public Task<OrganizationPage<CoverageGoalView>> CoverageGoals(Guid campaign,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{Page(offset);_=await Publication(campaign,ct);var rows=await db.CoverageGoals.AsNoTracking().Where(g=>g.CampaignId==campaign).OrderBy(g=>g.Name).ThenBy(g=>g.Id).Skip(offset).Take(21).ToArrayAsync(ct);var values=new List<CoverageGoalView>();foreach(var row in rows.Take(20))values.Add(await Goal(row.Id,null,ct));return new OrganizationPage<CoverageGoalView>(1,values.ToArray(),rows.Length>20?checked(offset+20):null);},ct);
    public Task<OrganizationPage<CoverageGoalView>> CoverageGoalHistory(Guid id,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? devicePilot=null)=>Snapshot(actor,devicePilot,async r=>{Page(offset);_=await Goal(id,null,ct);var versions=await db.Revisions.AsNoTracking().Where(v=>v.ResourceId==id&&v.Kind=="coverage-goal").OrderByDescending(v=>v.Revision).Skip(offset).Take(21).Select(v=>v.Revision).ToArrayAsync(ct);var values=new List<CoverageGoalView>();foreach(var revision in versions.Take(20))values.Add(await Goal(id,revision,ct));return new OrganizationPage<CoverageGoalView>(1,values.ToArray(),versions.Length>20?checked(offset+20):null);},ct);
}
